import datetime


_RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _is_digits(s):
    return len(s) > 0 and all(c in "0123456789" for c in s)


def _parse_field(text, lo, hi, is_dow=False):
    # returns set of values (with dow 7 mapped to 0)
    if text == "":
        raise ValueError("invalid field")
    parts = text.split(",")
    result = set()
    for item in parts:
        if item == "":
            raise ValueError("invalid item")
        if "/" in item:
            segs = item.split("/")
            if len(segs) != 2:
                raise ValueError("invalid step")
            left, right = segs
            if not _is_digits(right):
                raise ValueError("invalid step")
            step = int(right)
            if step < 1:
                raise ValueError("invalid step")
            if left == "*":
                a, b = lo, hi
            elif "-" in left:
                lr = left.split("-")
                if len(lr) != 2:
                    raise ValueError("invalid range")
                sa, sb = lr
                if not _is_digits(sa) or not _is_digits(sb):
                    raise ValueError("invalid range")
                a, b = int(sa), int(sb)
                if not (lo <= a <= hi and lo <= b <= hi):
                    raise ValueError("out of range")
                if a > b:
                    raise ValueError("reversed range")
            else:
                # step after single value, or empty, etc.
                raise ValueError("invalid step usage")
            v = a
            while v <= b:
                result.add(v)
                v += step
        else:
            if item == "*":
                for v in range(lo, hi + 1):
                    result.add(v)
            elif "-" in item:
                lr = item.split("-")
                if len(lr) != 2:
                    raise ValueError("invalid range")
                sa, sb = lr
                if not _is_digits(sa) or not _is_digits(sb):
                    raise ValueError("invalid range")
                a, b = int(sa), int(sb)
                if not (lo <= a <= hi and lo <= b <= hi):
                    raise ValueError("out of range")
                if a > b:
                    raise ValueError("reversed range")
                for v in range(a, b + 1):
                    result.add(v)
            else:
                if not _is_digits(item):
                    raise ValueError("invalid value")
                a = int(item)
                if not (lo <= a <= hi):
                    raise ValueError("out of range")
                result.add(a)
    if is_dow and 7 in result:
        result.add(0)
        result.discard(7)
    return result


def cron_next(expr, after):
    """Return the first minute strictly after `after` that matches the cron expression `expr`."""
    if not isinstance(expr, str):
        raise TypeError("expr must be str")
    if not isinstance(after, datetime.datetime):
        raise TypeError("after must be datetime")
    if after.tzinfo is not None:
        raise ValueError("after must be naive")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expr must have 5 fields")
    f_min, f_hour, f_dom, f_mon, f_dow = fields

    try:
        minutes = _parse_field(f_min, 0, 59)
        hours = _parse_field(f_hour, 0, 23)
        doms = _parse_field(f_dom, 1, 31)
        mons = _parse_field(f_mon, 1, 12)
        dows = _parse_field(f_dow, 0, 7, is_dow=True)
    except ValueError:
        raise ValueError("invalid expr")

    dom_star = (f_dom == "*")
    dow_star = (f_dow == "*")

    s_minutes = sorted(minutes)
    s_hours = sorted(hours)

    start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    limit_year = after.year + 8
    if limit_year > 9999:
        limit_year = 9999
    if start.year > limit_year:
        raise ValueError("no match within search limit")
    end_date = datetime.date(limit_year, 12, 31)

    cur = start.date()
    # iterate days
    one_day = datetime.timedelta(days=1)
    while cur <= end_date:
        if cur.month in mons:
            # day match
            if dom_star and dow_star:
                day_ok = True
            elif dom_star:
                # dow: Monday=0..Sunday=6 in python; cron 0=Sunday
                cron_dow = (cur.weekday() + 1) % 7
                day_ok = cron_dow in dows
            elif dow_star:
                day_ok = cur.day in doms
            else:
                cron_dow = (cur.weekday() + 1) % 7
                day_ok = (cur.day in doms) or (cron_dow in dows)
            if day_ok:
                if cur == start.date():
                    # need time >= start time
                    for h in s_hours:
                        if h < start.hour:
                            continue
                        if h == start.hour:
                            for m in s_minutes:
                                if m < start.minute:
                                    continue
                                return datetime.datetime(cur.year, cur.month, cur.day, h, m)
                        else:
                            return datetime.datetime(cur.year, cur.month, cur.day, h, s_minutes[0])
                    # no time left today -> next day
                else:
                    return datetime.datetime(cur.year, cur.month, cur.day, s_hours[0], s_minutes[0])
        cur += one_day
        # early exit: if cur year > limit (shouldn't happen due to end_date)
    raise ValueError("no match within search limit")

import datetime


def cron_next(expr, after):
    """Return the first minute strictly after `after` that matches the cron expression `expr`."""
    # 1. Type checks
    if not isinstance(expr, str):
        raise TypeError("expr must be str")
    # datetime.datetime is subclass of date; require exact datetime type check via isinstance datetime but not date-only
    if not isinstance(after, datetime.datetime):
        raise TypeError("after must be datetime.datetime")
    # 2. tzinfo check
    if after.tzinfo is not None:
        raise ValueError("after must be naive")

    # 3. Parse expr
    if not isinstance(expr, str):
        raise ValueError("invalid")  # unreachable
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("expr must have exactly 5 fields")

    ranges = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]

    def is_ascii_digits(s):
        return len(s) > 0 and all('0' <= c <= '9' for c in s)

    def parse_field(text, lo, hi):
        # comma-separated list of one or more items
        items = text.split(',')
        if len(items) == 0:
            raise ValueError(f"invalid field {text!r}")
        result = set()
        for item in items:
            if item == '':
                raise ValueError(f"invalid item in {text!r}")
            if '/' in item:
                pieces = item.split('/')
                if len(pieces) != 2:
                    raise ValueError(f"invalid step {item!r}")
                left, right = pieces
                if not is_ascii_digits(right):
                    raise ValueError(f"invalid step {item!r}")
                s = int(right)
                if s < 1:
                    raise ValueError(f"invalid step {item!r}")
                if left == '*':
                    a, b = lo, hi
                elif '-' in left:
                    ab = left.split('-')
                    if len(ab) != 2:
                        raise ValueError(f"invalid range {item!r}")
                    sa, sb = ab
                    if not is_ascii_digits(sa) or not is_ascii_digits(sb):
                        raise ValueError(f"invalid range {item!r}")
                    a, b = int(sa), int(sb)
                    if a < lo or a > hi or b < lo or b > hi:
                        raise ValueError(f"value out of range in {item!r}")
                    if a > b:
                        raise ValueError(f"A > B in {item!r}")
                else:
                    # step after single value or empty etc.
                    raise ValueError(f"invalid step {item!r}")
                v = a
                while v <= b:
                    result.add(v)
                    v += s
            else:
                if item == '*':
                    for v in range(lo, hi + 1):
                        result.add(v)
                elif '-' in item:
                    ab = item.split('-')
                    if len(ab) != 2:
                        raise ValueError(f"invalid range {item!r}")
                    sa, sb = ab
                    if not is_ascii_digits(sa) or not is_ascii_digits(sb):
                        raise ValueError(f"invalid range {item!r}")
                    a, b = int(sa), int(sb)
                    if a < lo or a > hi or b < lo or b > hi:
                        raise ValueError(f"value out of range in {item!r}")
                    if a > b:
                        raise ValueError(f"A > B in {item!r}")
                    for v in range(a, b + 1):
                        result.add(v)
                else:
                    if not is_ascii_digits(item):
                        raise ValueError(f"invalid item {item!r}")
                    v = int(item)
                    if v < lo or v > hi:
                        raise ValueError(f"value out of range in {item!r}")
                    result.add(v)
        return result

    try:
        minute_set = parse_field(parts[0], 0, 59)
        hour_set = parse_field(parts[1], 0, 23)
        dom_set = parse_field(parts[2], 1, 31)
        month_set = parse_field(parts[3], 1, 12)
        dow_set_raw = parse_field(parts[4], 0, 7)
    except ValueError:
        raise
    except Exception:
        raise ValueError("invalid expr")

    # normalize dow 7 -> 0
    dow_set = set()
    for v in dow_set_raw:
        if v == 7:
            dow_set.add(0)
        else:
            dow_set.add(v)

    dom_star = (parts[2] == "*")
    dow_star = (parts[4] == "*")

    minutes_sorted = sorted(minute_set)
    hours_sorted = sorted(hour_set)

    # helper: next value >= x in sorted list, or None
    import bisect

    def day_matches(dt_date_year, dt_date_month, dt_date_day):
        # month check done outside, but keep day rule
        if dom_star and dow_star:
            return True
        in_dom = dt_date_day in dom_set
        # python weekday Monday=0..Sunday=6 -> cron Sunday=0
        cron_dow = (datetime.date(dt_date_year, dt_date_month, dt_date_day).weekday() + 1) % 7
        in_dow = cron_dow in dow_set
        if dom_star:
            return in_dow
        if dow_star:
            return in_dom
        return in_dom or in_dow

    # Search bounds
    ymax = after.year + 8
    if ymax > 9999:
        ymax = 9999
    limit = datetime.datetime(ymax, 12, 31, 23, 59, 0, 0)

    start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    # if start year > ymax -> no result
    if start > limit:
        raise ValueError("no match within search limit")

    # Iterate day by day
    cur_day = datetime.date(start.year, start.month, start.day)
    end_day = datetime.date(ymax, 12, 31)
    first = True
    one_day = datetime.timedelta(days=1)
    while cur_day <= end_day:
        y, m, d = cur_day.year, cur_day.month, cur_day.day
        if m in month_set and day_matches(y, m, d):
            if first:
                h0 = start.hour
                m0 = start.minute
            else:
                h0 = 0
                m0 = 0
            # find hour
            idx_h = bisect.bisect_left(hours_sorted, h0)
            for hi in range(idx_h, len(hours_sorted)):
                h = hours_sorted[hi]
                if h > h0:
                    mm_needed = 0
                    idx_m = 0
                else:
                    mm_needed = m0
                    idx_m = bisect.bisect_left(minutes_sorted, mm_needed)
                if idx_m < len(minutes_sorted):
                    cand = datetime.datetime(y, m, d, h, minutes_sorted[idx_m], 0, 0)
                    if cand >= start and cand <= limit:
                        return cand
                    elif cand > limit:
                        raise ValueError("no match within search limit")
                # else no minute in this hour, continue to next hour
            # no hour/minute this day -> go to next day
        # advance
        first = False
        # skip quickly if month not in set? Just step day by day (max ~2922 iterations) - fine.
        # Optimization: if whole month not matching, jump to first day of next month.
        if m not in month_set:
            # jump to first of next month
            if m == 12:
                cur_day = datetime.date(y + 1, 1, 1) if y + 1 <= 9999 else end_day + one_day
            else:
                cur_day = datetime.date(y, m + 1, 1)
            continue
        cur_day = cur_day + one_day

    raise ValueError("no match within search limit")

import datetime
import bisect


_RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _is_digits(s):
    return len(s) > 0 and all('0' <= c <= '9' for c in s)


def _parse_field(text, lo, hi):
    # returns set of values; raises ValueError if invalid
    if text == "":
        raise ValueError("empty field")
    parts = text.split(",")
    values = set()
    for item in parts:
        if item == "":
            raise ValueError("empty item")
        # split step
        if "/" in item:
            segs = item.split("/")
            if len(segs) != 2:
                raise ValueError("bad step")
            base, step_s = segs
            if not _is_digits(step_s):
                raise ValueError("bad step")
            step = int(step_s)
            if step < 1:
                raise ValueError("bad step")
            if base == "*":
                a, b = lo, hi
            elif "-" in base:
                bs = base.split("-")
                if len(bs) != 2:
                    raise ValueError("bad range")
                a_s, b_s = bs
                if not _is_digits(a_s) or not _is_digits(b_s):
                    raise ValueError("bad range")
                a, b = int(a_s), int(b_s)
                if a < lo or a > hi or b < lo or b > hi:
                    raise ValueError("out of range")
                if a > b:
                    raise ValueError("reversed range")
            else:
                # step after single value, e.g. 5/15 -> invalid
                raise ValueError("bad step base")
            v = a
            while v <= b:
                values.add(v)
                v += step
        else:
            if item == "*":
                for v in range(lo, hi + 1):
                    values.add(v)
            elif "-" in item:
                bs = item.split("-")
                if len(bs) != 2:
                    raise ValueError("bad range")
                a_s, b_s = bs
                if not _is_digits(a_s) or not _is_digits(b_s):
                    raise ValueError("bad range")
                a, b = int(a_s), int(b_s)
                if a < lo or a > hi or b < lo or b > hi:
                    raise ValueError("out of range")
                if a > b:
                    raise ValueError("reversed range")
                for v in range(a, b + 1):
                    values.add(v)
            else:
                if not _is_digits(item):
                    raise ValueError("bad value")
                v = int(item)
                if v < lo or v > hi:
                    raise ValueError("out of range")
                values.add(v)
    if not values:
        raise ValueError("empty")
    return values


def cron_next(expr, after):
    """Return the first minute strictly after `after` that matches the cron expression `expr`.

    Arguments:
        expr: a str of exactly 5 fields separated by whitespace (as split by str.split()):
            minute (0-59), hour (0-23), day of month (1-31), month (1-12) and day of week
            (0-7: 0 and 7 are both Sunday, 1 is Monday, ..., 6 is Saturday).
        after: a naive datetime.datetime (tzinfo is None).

    Errors, checked in this order:
        1. TypeError if expr is not a str, or after is not a datetime.datetime (a
           datetime.date that is not a datetime is not accepted).
        2. ValueError if after.tzinfo is not None.
        3. ValueError if expr is invalid (see Syntax).
        4. ValueError if no minute matches within the search limit (see Search).

    Syntax
        Each field is a comma-separated list of one or more items. An item is one of:
            *        every value in the field's range
            N        the single value N
            A-B      the values A to B inclusive; A must not be greater than B
            */S      every S-th value of the field's range, starting at its lowest value
            A-B/S    A, A+S, A+2S, ... up to B
        N, A, B and S are written with ASCII digits 0-9 only; leading zeros are allowed
        ("05" is 5). Every value must lie in the field's range and S must be at least 1.
        Anything else is invalid, for example an empty item ("1,,2"), a step after a
        single value ("5/15"), names such as "MON" or "JAN", "?", or a number of fields
        other than 5.

    Matching
        A minute matches if its minute, hour and month are in their fields and its day
        matches. The day rule depends on whether the day-of-month and day-of-week fields
        are exactly the str "*" (any other text, even "*/1" or "0-7", is restricted):
          - both are "*": every day matches;
          - exactly one is "*": the day must be in the other field;
          - neither is "*": the day matches if its day of month is in the day-of-month
            field OR its day of week is in the day-of-week field.
        A day of month that a month does not have (such as 31 in April) never matches.
        Dates follow the proleptic Gregorian calendar of datetime (2100 is not a leap year).

    Search
        The result is the earliest datetime with second 0 and microsecond 0 that is
        greater than `after` and matches. So the seconds and microseconds of `after`
        count only for "greater than": after 10:00:30 the first candidate is 10:01.
        Only results with year <= after.year + 8 (and <= 9999) are considered; if there
        is none, ValueError is raised.
        Each call must finish in well under a second, even when the result is years
        after `after` or there is no result.

    Returns a naive datetime.datetime.
    """
    # 1
    if not isinstance(expr, str) or not isinstance(after, datetime.datetime):
        raise TypeError("bad types")
    # 2
    if after.tzinfo is not None:
        raise ValueError("tz-aware")
    # 3
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("need 5 fields")
    try:
        min_set = _parse_field(fields[0], 0, 59)
        hour_set = _parse_field(fields[1], 0, 23)
        dom_set = _parse_field(fields[2], 1, 31)
        mon_set = _parse_field(fields[3], 1, 12)
        dow_raw = _parse_field(fields[4], 0, 7)
    except ValueError:
        raise ValueError("invalid expr")
    # normalize dow: 7 -> 0
    dow_set = set()
    for v in dow_raw:
        if v == 7:
            dow_set.add(0)
        else:
            dow_set.add(v)

    dom_star = (fields[2] == "*")
    dow_star = (fields[4] == "*")

    mins = sorted(min_set)
    hours = sorted(hour_set)

    start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    max_year = after.year + 8
    if max_year > 9999:
        max_year = 9999
    # end exclusive: Jan 1 of max_year+1
    if max_year >= 9999:
        end_date = datetime.date(9999, 12, 31)
    else:
        end_date = datetime.date(max_year + 1, 1, 1) - datetime.timedelta(days=1)

    cur = start.date()
    last = end_date
    # iterate days
    one_day = datetime.timedelta(days=1)
    while cur <= last:
        if cur.month in mon_set:
            # day match
            if dom_star and dow_star:
                ok = True
            elif dom_star:
                cron_dow = (cur.weekday() + 1) % 7
                ok = cron_dow in dow_set
            elif dow_star:
                ok = cur.day in dom_set
            else:
                cron_dow = (cur.weekday() + 1) % 7
                ok = (cur.day in dom_set) or (cron_dow in dow_set)
            if ok:
                if cur == start.date():
                    sh, sm = start.hour, start.minute
                    # find hour
                    hi = bisect.bisect_left(hours, sh)
                    for h in hours[hi:]:
                        if h == sh:
                            mi = bisect.bisect_left(mins, sm)
                            if mi < len(mins):
                                return datetime.datetime(cur.year, cur.month, cur.day, h, mins[mi])
                            # else next hour
                        elif h > sh:
                            return datetime.datetime(cur.year, cur.month, cur.day, h, mins[0])
                    # no time today -> next day
                else:
                    return datetime.datetime(cur.year, cur.month, cur.day, hours[0], mins[0])
        cur += one_day

    raise ValueError("no match within search limit")

def expr_eval(s):
    """Evaluate the integer expression in the str `s` and return its value as an int.

    Errors:
        TypeError if s is not a str.
        ValueError if s is not a valid expression (see Syntax). All of s is checked before
        anything is evaluated, so a syntax error anywhere raises ValueError even if
        evaluating an earlier part would raise a different error.
        During evaluation (see Evaluation): ZeroDivisionError if the right operand of //
        or % is 0; ValueError if the exponent of ** is negative (including 0 ** -1).

    Syntax
        Tokens are integer literals (one or more ASCII digits 0-9; leading zeros are
        allowed, so "007" is 7), the operators + - * // % ** and the parentheses ( and ).
        Whitespace (any character c with c.isspace()) may appear between tokens and is
        ignored; any other character is invalid. "**" and "//" are single tokens and
        cannot contain whitespace: "* *" is two * tokens, and a lone "/" is invalid.

        Grammar, from lowest to highest precedence:
            expr  := term (("+" | "-") term)*           left-associative
            term  := unary (("*" | "//" | "%") unary)*  left-associative
            unary := ("+" | "-") unary | power
            power := atom ("**" unary)?                 so ** is right-associative
            atom  := integer | "(" expr ")"
        So ** binds tighter than a unary sign on its left (-2**2 is -4, (-2)**2 is 4), its
        right operand may start with unary signs (2**-1 is valid syntax and fails during
        evaluation), and 2**3**2 is 2**(3**2) = 512. Unary signs can repeat: "--2" is 2
        and "1 - -2" is 3. An empty or all-whitespace string, and anything else the grammar
        does not produce (for example "()", "1 2", "2 * * 3", "(1" or "1 +"), is invalid.

    Evaluation
        Integers are unbounded (Python int). + - * are integer arithmetic; // and % are
        floor division and modulo with Python's semantics (7 // -2 is -4, 7 % -2 is -1,
        -7 % 2 is 1); ** is integer power with a non-negative exponent (0 ** 0 is 1).
        Unary minus negates and unary plus does nothing.
        Evaluation is left to right: for each binary operator, the left operand is
        evaluated fully, then the right operand, then the operator is applied. The first
        error reached in this order is the one raised.
        Nesting can be deep and expressions long: s may have 5,000 nested parentheses or
        unary signs, or 200,000 tokens.
    """
    if not isinstance(s, str):
        raise TypeError

    # ---- tokenize ----
    # token: ('NUM', int) | ('OP', str) where str in + - * // % ** | ('LP',) | ('RP',)
    tokens = []
    n = len(s)
    i = 0
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if '0' <= c <= '9':
            j = i + 1
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(('NUM', int(s[i:j])))
            i = j
            continue
        if c == '(':
            tokens.append(('LP',))
            i += 1
            continue
        if c == ')':
            tokens.append(('RP',))
            i += 1
            continue
        if c == '+':
            tokens.append(('OP', '+'))
            i += 1
            continue
        if c == '-':
            tokens.append(('OP', '-'))
            i += 1
            continue
        if c == '*':
            if i + 1 < n and s[i + 1] == '*':
                tokens.append(('OP', '**'))
                i += 2
            else:
                tokens.append(('OP', '*'))
                i += 1
            continue
        if c == '/':
            if i + 1 < n and s[i + 1] == '/':
                tokens.append(('OP', '//'))
                i += 2
            else:
                raise ValueError("invalid expression")
            continue
        if c == '%':
            tokens.append(('OP', '%'))
            i += 1
            continue
        raise ValueError("invalid expression")

    # ---- parse (shunting-yard) to RPN ----
    # RPN items: ('NUM', v) | ('U+',) | ('U-',) | ('+',) | ('-',) | ('*',) | ('//',) | ('%',) | ('**',)
    output = []
    opstack = []  # entries: 'LP', 'U+', 'U-', '+', '-', '*', '//', '%', '**'
    expect_operand = True

    def is_unary_top(t):
        return t == 'U+' or t == 'U-'

    def prec_binary(t):
        if t == '+' or t == '-':
            return 1
        if t == '*' or t == '//' or t == '%':
            return 2
        if t == '**':
            return 4
        return -1

    for tok in tokens:
        kind = tok[0]
        if expect_operand:
            if kind == 'NUM':
                output.append(tok)
                expect_operand = False
            elif kind == 'LP':
                opstack.append('LP')
                # still expect operand
            elif kind == 'OP' and (tok[1] == '+' or tok[1] == '-'):
                # unary
                opstack.append('U' + tok[1])
                # still expect operand
            else:
                raise ValueError("invalid expression")
        else:
            # expect binary operator or ')'
            if kind == 'RP':
                # pop until LP
                found = False
                while opstack:
                    t = opstack.pop()
                    if t == 'LP':
                        found = True
                        break
                    output.append((t,))
                if not found:
                    raise ValueError("invalid expression")
                # after ')' we have an operand
                expect_operand = False
            elif kind == 'OP':
                o = tok[1]
                if o == '**':
                    # push always (right-assoc, never pops unary)
                    opstack.append('**')
                    expect_operand = True
                elif o in ('+', '-', '*', '//', '%'):
                    p = prec_binary(o)
                    while opstack:
                        t = opstack[-1]
                        if t == 'LP':
                            break
                        if t == '**':
                            # ** has higher prec than all these -> pop
                            output.append((opstack.pop(),))
                            continue
                        if is_unary_top(t):
                            output.append((opstack.pop(),))
                            continue
                        # binary on stack
                        if prec_binary(t) >= p:
                            output.append((opstack.pop(),))
                            continue
                        break
                    opstack.append(o)
                    expect_operand = True
                else:
                    raise ValueError("invalid expression")
            else:
                # NUM or LP right after operand -> invalid ("1 2", "2(3)")
                raise ValueError("invalid expression")

    if expect_operand:
        # empty, trailing operator, dangling '(' etc.
        raise ValueError("invalid expression")
    # drain
    while opstack:
        t = opstack.pop()
        if t == 'LP':
            raise ValueError("invalid expression")
        output.append((t,))

    # ---- evaluate RPN ----
    stack = []
    for item in output:
        if item[0] == 'NUM':
            stack.append(item[1])
        elif item[0] == 'U+':
            try:
                a = stack.pop()
            except IndexError:
                raise ValueError("invalid expression")
            stack.append(a)
        elif item[0] == 'U-':
            try:
                a = stack.pop()
            except IndexError:
                raise ValueError("invalid expression")
            stack.append(-a)
        else:
            op = item[0]
            try:
                b = stack.pop()
                a = stack.pop()
            except IndexError:
                raise ValueError("invalid expression")
            if op == '+':
                stack.append(a + b)
            elif op == '-':
                stack.append(a - b)
            elif op == '*':
                stack.append(a * b)
            elif op == '//':
                if b == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                stack.append(a // b)
            elif op == '%':
                if b == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                stack.append(a % b)
            elif op == '**':
                if b < 0:
                    raise ValueError("negative exponent")
                stack.append(a ** b)
            else:
                raise ValueError("invalid expression")
    if len(stack) != 1:
        raise ValueError("invalid expression")
    return stack[0]
